import { GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { Logger } from '@nestjs/common';
import { link, mkdir, readFile, unlink, writeFile } from 'fs/promises';
import { dirname, join, resolve, sep } from 'path';

/** Where attachment bytes live. Keys are generated by the API, never by users. */
export interface ObjectStorage {
  readonly name: string;
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
}

// <tenant>/<entity>/<sha256 prefix>/<uuid>; keys without a tenant prefix predate multi-tenancy.
const KEY = /^(?:[a-z][a-z0-9-]{1,30}\/)?[a-z]+\/[0-9a-f]{2}\/[0-9a-f-]{36}$/;
function assertKey(key: string): void {
  if (!KEY.test(key)) throw new Error(`Refusing unexpected storage key "${key}"`);
}

/** Files on a local directory (a Docker volume in production). */
export class LocalStorage implements ObjectStorage {
  readonly name = 'local';
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private path(key: string): string {
    assertKey(key);
    const p = resolve(join(this.root, key));
    if (!p.startsWith(this.root + sep)) throw new Error('Storage path escapes the attachments directory');
    return p;
  }

  async put(key: string, body: Buffer): Promise<void> {
    const p = this.path(key);
    await mkdir(dirname(p), { recursive: true });
    // Write to a temporary name, then hard-link it into place: a crash never
    // leaves a half-written file under the real name, and unlike rename a link
    // fails if the name exists, so stored evidence is never overwritten.
    const tmp = `${p}.${process.pid}.${Date.now()}.tmp`;
    await writeFile(tmp, body, { flag: 'wx' });
    try {
      await link(tmp, p);
    } finally {
      await unlink(tmp);
    }
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.path(key));
  }
}

/** Any S3-compatible service: AWS S3, MinIO, Cloudflare R2, Wasabi… */
export class S3Storage implements ObjectStorage {
  readonly name = 's3';

  constructor(private readonly client: Pick<S3Client, 'send'>, private readonly bucket: string, private readonly prefix = '') {}

  async put(key: string, body: Buffer, contentType: string): Promise<void> {
    assertKey(key);
    await this.client.send(new PutObjectCommand({
      Bucket: this.bucket, Key: this.prefix + key, Body: body, ContentType: contentType, ServerSideEncryption: 'AES256',
    }));
  }

  async get(key: string): Promise<Buffer> {
    assertKey(key);
    const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: this.prefix + key }));
    const body = res.Body as { transformToByteArray?: () => Promise<Uint8Array> } | undefined;
    if (!body?.transformToByteArray) throw new Error(`Object ${key} has no body`);
    return Buffer.from(await body.transformToByteArray());
  }
}

/** Pick the driver from STORAGE_DRIVER (local | s3). */
export function storageFromEnv(env = process.env): ObjectStorage {
  const driver = (env.STORAGE_DRIVER || 'local').toLowerCase();
  const log = new Logger('Storage');
  if (driver === 's3') {
    if (!env.S3_BUCKET) throw new Error('S3_BUCKET is required when STORAGE_DRIVER=s3');
    const client = new S3Client({
      region: env.S3_REGION || 'us-east-1',
      endpoint: env.S3_ENDPOINT || undefined,
      forcePathStyle: env.S3_FORCE_PATH_STYLE === 'true' || env.S3_FORCE_PATH_STYLE === '1',
      // Credentials come from the standard AWS chain (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY, IAM role…).
    });
    log.log(`Attachments stored in S3 bucket ${env.S3_BUCKET}${env.S3_ENDPOINT ? ` at ${env.S3_ENDPOINT}` : ''}`);
    return new S3Storage(client, env.S3_BUCKET, env.S3_PREFIX || '');
  }
  if (driver !== 'local') throw new Error(`Unknown STORAGE_DRIVER "${driver}" (use local or s3)`);
  const dir = env.ATTACHMENTS_DIR || './data/attachments';
  log.log(`Attachments stored on disk in ${resolve(dir)}`);
  return new LocalStorage(dir);
}
